mapper.update:
    UPDATE company
    SET
		material_use_yn = #{material_use_yn},
        update_date          = CURRENT_TIMESTAMP,
        update_by            = #{update_by}
    WHERE company_code = #{company_code}

	UPDATE company_option
	   SET option_value = #{option_value}
	 WHERE company_code = #{company_code}
	   AND option_code = #{option_code}

UPDATE company
   SET com_de_minimis_rate = ${de_minimis_rate}
       ,com_rvc_rate = ${rvc_rate}
 WHERE company_code = #{company_code}

UPDATE division
   SET div_de_minimis_rate = ${de_minimis_rate}
       ,div_rvc_rate = ${rvc_rate}
 WHERE company_code = #{company_code}
   AND division_code = #{target_code}

UPDATE fta_master
   SET com_de_minimis_rate = ${de_minimis_rate}
       ,com_rvc_rate = ${rvc_rate}
 WHERE company_code = #{company_code}
   AND fta_code = #{target_code}
